  if(a==='publish-build'){buildTasks[0].status='已完成';buildTasks[0].stage='知识发布完成';toast('知识已发布，正式版本 V1.0 已生成');return go('build')}
  if(a==='back-work-queue'){if(state.route==='review'||state.route==='raw-review')state.reviewWorkItem=null;else if(state.route==='approval')state.approvalWorkItem=null;else state.certificationWorkItem=null;return render()}
